def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:n+1]]

    min_val = min(a)

    for x in a:
        if x % min_val != 0:
            print("-1")
            return

    print(min_val)

